import {stopwatchPage,bindStopwatch} from './stopwatch.js';
import {imminentBirth} from './birth-ui.js';
import {pageIcons} from './page-icons.js';
import {pediatricArrest,bindArrestBirth} from './pediatric-arrest-birth.js';
import {defibGuide,bindDefibGuide} from './defib-guide.js';
import {traumaArrestPanel,rememberTraumaArrest,bindTraumaArrest} from './trauma-arrest.js';
import {pulsePanel,refreshPulseTimer,createTimerAudio,processTimerAlerts,clearTimerAlerts,timerPhase,EPI_WARNING} from './arrest-timers.js';
import {dispatchTimerPanel,refreshDispatchTimer,bindArrestTools} from './arrest-tools.js';
import {pediatricUI} from './pediatric-ui.js';
import {traumaActions,shockPanel,burnsPanel,painPanel,bindClinicalTools} from './clinical-tools.js';
import {postCall,bindPostCall} from './post-call.js';
import {medicationReference,calculators,referenceUI,setConcentration,sedationDosing,bindSedationDosing} from './medication-ui.js';
import {kgFrom} from './calculations.js';
import {modules,causes,protocol,checklistId} from './data.js';
const icons={burns:'<path d="M5 20c-4-4-1-8 1-11l1 4c0-4 2-7 5-11 0 4 4 6 5 10l2-3c3 4 4 8 0 11"/><circle cx="12" cy="11" r="2"/><path d="M12 13v5m-4-3 4-1 4 1m-4 3-3 4m3-4 3 4"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',pulse:'<path d="M2 12h5l3-8 4 16 3-8h5"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-7l1-7Z"/>',syringe:'<path d="m18 2 4 4m-3-1-5 5m-8 2 6 6m-9 3 3-3m0 0-1-4 9-9 5 5-9 9-4-1Z"/>',airway:'<path d="M12 2v9M8 3v8l-5 7a2 2 0 0 0 2 3h3l4-7 4 7h3a2 2 0 0 0 2-3l-5-7V3"/>',brain:'<path d="M12 5c-4-5-8 0-6 3-5 1-4 7-1 8-1 5 5 7 7 3V5Zm0 0c4-5 8 0 6 3 5 1 4 7 1 8 1 5-5 7-7 3M6 8l3 2m-4 6 4-2m9-6-3 2m4 6-4-2"/>',shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4Z"/><path d="M12 8v8m-4-4h8"/>',child:'<circle cx="12" cy="5" r="3"/><path d="M5 10h14m-7-2v8m0-1-5 7m5-7 5 7"/>',book:'<path d="M12 5c-4-3-7-3-10-2v16c4-1 7 0 10 2 3-2 6-3 10-2V3c-3-1-6-1-10 2Zm0 0v16"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',reset:'<path d="M3 10a9 9 0 1 1 2 8M3 3v7h7"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>'};
Object.assign(icons,{
 power:'<path d="M12 2v10m6.36-5.36a9 9 0 1 1-12.72 0"/>',
 heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/><path d="M3 12h4l2-4 3 8 2-4h7"/>',
 drop:'<path d="M12 2C9 7 5 10 5 14a7 7 0 0 0 14 0c0-4-4-7-7-12Z"/><path d="M8 14a4 4 0 0 0 4 4"/>',
 flask:'<path d="M9 2h6M10 2v7L4 19a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3L14 9V2M7 14h10"/><circle cx="10" cy="17" r=".8"/>',
 microbe:'<circle cx="12" cy="12" r="6"/><path d="M12 2v4m0 12v4M2 12h4m12 0h4M5 5l3 3m8 8 3 3M5 19l3-3m8-8 3-3"/><circle cx="10" cy="10" r="1"/><circle cx="14" cy="14" r="1"/>',
 bandage:'<rect x="2" y="8" width="20" height="8" rx="4" transform="rotate(-45 12 12)"/><path d="m9 9 6 6m-9-2 1 1m10-4 1 1"/>',
 atom:'<ellipse cx="12" cy="12" rx="10" ry="4"/><ellipse cx="12" cy="12" rx="10" ry="4" transform="rotate(60 12 12)"/><ellipse cx="12" cy="12" rx="10" ry="4" transform="rotate(120 12 12)"/><circle cx="12" cy="12" r="1"/>'
});
Object.assign(icons,pageIcons);
const amsCauseIcons={oxygen:'airway',glucose:'drop',stroke:'brain',seizure:'bolt',toxic:'flask',cardiac:'pulse',infection:'microbe',trauma:'bandage',metabolic:'atom'};
const crest=()=>'<span class="crest"><img src="assets/woodlawn-fd-crest.svg" alt="Woodlawn Fire Department · Station 96 crest" width="640" height="640"></span>';
const sectionColors=['red','blue','teal','purple','orange'];
const checklistColors={sick:['blue','teal','purple','red'],arrest:['blue','red','teal','purple'],cardio:['blue','red','teal'],sedation:['blue','purple','teal','orange'],intubation:['blue','red','teal','purple'],ams:['teal'],trauma:sectionColors};
const icon=(n)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.grid}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const blank=()=>({checks:{},causes:{},fields:{},stopwatch:{elapsed:0,started:null},started:null,elapsed:0,running:false,age:null,adultMax:'200',filter:'',epiInterval:5,epiDueAt:null,pulseDueAt:null,timerSound:true,timerAlerts:{}});
let state;try{state=Object.assign(blank(),JSON.parse(sessionStorage.getItem('wfd-encounter-v1')||'{}'));}catch{state=blank()}
state.adultMax='200';
let page=location.hash.slice(1)||'home',query='',modal=false;
const pageLabel=()=>({home:'Overview',stopwatch:'Stopwatch','post-call':'Post-call checklist',pediatric:'Pediatric reference','pediatric-arrest':'Pediatric cardiac arrest',birth:'Imminent birth',protocol:'Protocol library',medications:'Unusual drugs',calculators:'Dose & drip calculators'}[page]||modules.find(m=>m.id===page)?.short||'Overview');
const save=()=>{try{sessionStorage.setItem('wfd-encounter-v1',JSON.stringify(state));}catch{}};
// CSN now records narrative completion; remove the retired free-text value.
for(const retired of ['post-csn','post-service']){if(Object.hasOwn(state.fields,retired)){delete state.fields[retired];save();}}
const count=m=>m.sections.reduce((n,s)=>n+s[1].length,0);
const completed=m=>m.sections.reduce((n,section,si)=>n+section[1].filter((item,ii)=>state.checks[checklistId(m.id,si,item,ii)]).length,0);
const source=(label,p=1)=>`<a class="source" href="${protocol}#page=${p}" target="_blank" rel="noopener">${icon('book')}${esc(label)} ↗</a>`;
function nav(id,label,i){return `<button class="nav-item ${page===id?'active':''}" data-page="${id}" ${page===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${page===id?'<i></i>':''}</button>`;}
function shell(){if(page==='stopwatch')return stopwatchPage(state,icon);return `<aside class="sidebar"><a href="#home" class="brand">${crest()}<span>WOODLAWN<span>FIRE DEPARTMENT</span></span></a><div class="sidebar-label">EMS FIELD GUIDE</div>${nav('home','Overview','grid')}${nav('stopwatch','Stopwatch','clock')}<div class="sidebar-label space">CHECKLISTS</div>${modules.map(m=>nav(m.id,m.short,m.icon)).join('')}${nav('pediatric-arrest','Pediatric cardiac arrest','child-arrest')}${nav('birth','Imminent birth','birth')}${nav('post-call','Post-call checklist','finish')}<div class="sidebar-label space">QUICK REFERENCE</div>${nav('medications','Unusual drugs','mystery')}${nav('calculators','Dose & drip calculators','calculator')}${nav('pediatric','Pediatric calculator','child-smile')}${nav('protocol','Protocol library','book')}<div class="side-footer"><span class="status-dot"></span> 2026 Southwest Ohio<div>Version 2.9.26 · Review prototype</div></div></aside><div class="workspace"><header><div class="crumb">EMS Field Guide <span>/</span> <b>${pageLabel()}</b></div><button class="button small" data-action="new">${icon('plus')} New encounter</button></header><main>${page==='home'?home():page==='post-call'?postCall(state.fields,icon):page==='pediatric'?pediatric():page==='pediatric-arrest'?pediatricArrest(state,source,icon,pulsePanel(state,icon,source)+epiPanel('P601',152)+timerSoundPanel(),checklistRow):page==='birth'?imminentBirth(state,source,icon,checklistRow):page==='protocol'?library():page==='medications'?medicationReference(state.fields,source,icon):page==='calculators'?calculators(state.fields,source):detail(modules.find(m=>m.id===page)||modules[0])}</main><footer>WOODLAWN FD <span>Prototype · Clinical validation pending</span></footer></div>${modal?dialog():''}`;}
function home(){const guideCards=[{id:'pediatric-arrest',title:'Pediatric cardiac arrest',color:'red',icon:'child-arrest',tag:'PEDIATRIC CODE',sections:[]},{id:'birth',title:'Imminent birth',color:'teal',icon:'birth',tag:'MOTHER + NEWBORN',sections:[]}];const matches=[...modules,...guideCards].filter(m=>(m.title+' '+m.sections.map(s=>s[0]).join(' ')).toLowerCase().includes(query.toLowerCase()));return `<a class="overview-protocol" href="${protocol}#page=1" target="_blank" rel="noopener"><span class="overview-protocol-icon">${icon('book')}</span><span><span class="eyebrow">SOUTHWEST OHIO · 2026</span><h1>Open EMS Protocols</h1></span><span class="overview-protocol-arrow">${icon('arrow')}</span></a><button class="quick-tool stopwatch-launch" data-page="stopwatch">${icon('clock')}<span><b>Stopwatch</b></span>${icon('arrow')}</button><div class="dashboard"><div><div class="section-top"><h2>Clinical checklists <span>${String(modules.length+guideCards.length).padStart(2,'0')}</span></h2><label class="search">${icon('search')}<input id="search" aria-label="Search checklists" placeholder="Find a checklist…" value="${esc(query)}"><kbd>/</kbd></label></div><div class="cards">${matches.map(m=>`<button class="module-card ${m.color}" data-page="${m.id}"><div class="card-top"><div class="module-icon">${icon(m.icon)}</div>${icon('arrow')}</div><h3>${m.title}</h3></button>`).join('')||'<p class="empty">No matching checklist. Try “airway” or “trauma”.</p>'}</div><button class="quick-tool post-call-launch" data-page="post-call">${icon('finish')}<span><b>Post-call checklist</b></span>${icon('arrow')}</button><div class="quick-tool-grid"><button class="quick-tool red" data-page="medications">${icon('mystery')}<span><b>Unusual drugs</b></span>${icon('arrow')}</button><button class="quick-tool blue" data-page="calculators">${icon('calculator')}<span><b>Dose & drip calculators</b></span>${icon('arrow')}</button></div><button class="pediatric-banner" data-page="pediatric"><div class="module-icon">${icon('child-smile')}</div><div><h3>Pediatric quick reference</h3></div><span class="round-arrow">${icon('arrow')}</span></button></div><aside class="right-rail">${timerPanel()}</aside></div><div class="review-banner"><span class="mini-badge">DRAFT</span>Review prototype · Verify before field use.<button data-page="protocol">View sources ${icon('arrow')}</button></div>`;}
function timerPanel(){return `<section class="panel timer"><div class="section-top"><h2>${icon('clock')} Event timer</h2><span class="timer-label">ELAPSED</span></div><div class="timer-digits" role="timer">${timerText()}</div><div class="timer-actions"><button class="button primary" data-action="timer">${state.running?'Pause':'Start timer'}</button><button class="button icon-button" data-action="reset-timer" aria-label="Reset timer">${icon('reset')}</button></div><p class="muted">Manual elapsed timer; no clinical alarms.</p></section>`;}
function timerText(){const ms=state.elapsed+(state.running?Date.now()-state.started:0);const s=Math.floor(ms/1000);return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}
function epiInterval(){return [3,4,5].includes(Number(state.epiInterval))?Number(state.epiInterval):5;}
function epiSeconds(){return state.epiDueAt===null?epiInterval()*60:Math.max(0,Math.ceil((state.epiDueAt-Date.now())/1000));}
function epiText(){const s=epiSeconds();return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}
function epiStatus(){return state.epiDueAt===null?'Ready after first dose':epiSeconds()===0?'NEXT DOSE DUE':epiSeconds()<=EPI_WARNING?'EPI DUE SOON · PREPARE NEXT DOSE':'Until next dose';}
function epiPanel(code='C300',protocolPage=75){return `<section class="epi-panel ${timerPhase(state.epiDueAt,epiInterval()*60,EPI_WARNING)}" aria-labelledby="epi-title">
  <div class="epi-heading"><h2 id="epi-title">${icon('clock')} Epi dose timer</h2>${source('EPI PROTOCOL · '+code,protocolPage)}</div>
  <div class="epi-body"><div><div class="epi-digits" role="timer" aria-label="Time until next epinephrine dose">${epiText()}</div><p class="epi-status" role="status" aria-live="polite">${epiStatus()}</p></div>
    <div class="epi-controls"><label class="field">Dose interval<select id="epi-interval" ${state.epiDueAt!==null?'disabled':''}>${[3,4,5].map(n=>`<option value="${n}" ${epiInterval()===n?'selected':''}>${n} minutes${n===5?' (default)':''}</option>`).join('')}</select></label>
      <button class="button epi-start" data-action="epi-dose">Epi given · ${state.epiDueAt===null?'start':'restart'} ${epiInterval()} min</button>
      <button class="button" data-action="clear-epi" ${state.epiDueAt===null?'disabled':''}>Clear timer</button>
    </div>
  </div><p class="epi-note">Start after administration. Repeat per arrest protocol (3–5 min). Low thrum at 30 seconds remaining.</p>
</section>`;}
const timerAudio=createTimerAudio(()=>refreshTimerSoundStatus());
function timerSoundStatus(){return state.timerSound===false?'Timer sounds muted':timerAudio.ready()?'Timer sounds ready · check device volume':'Tap a timer or test sound to enable audio';}
function refreshTimerSoundStatus(){const label=document.querySelector('.timer-sound-status');if(label&&label.textContent!==timerSoundStatus())label.textContent=timerSoundStatus();}
function timerSoundPanel(){return `<section class="timer-sounds" aria-label="Timer alert sounds"><div><b>Distinct timer alerts</b><p class="timer-sound-status" role="status" aria-live="polite">${timerSoundStatus()}</p></div><div class="timer-sound-controls"><button class="button small" data-action="test-pulse-sound">Test pulse ding</button><button class="button small" data-action="test-epi-sound">Test epi thrum</button><button class="button small" data-action="toggle-timer-sound" aria-pressed="${state.timerSound!==false}">${state.timerSound===false?'Unmute sounds':'Mute sounds'}</button></div><p class="timer-audio-note">Sounds need this page open and your device volume on. Browser sleep or a locked screen can delay alerts.</p></section>`;}
async function testTimerSound(kind){state.timerSound=true;save();await timerAudio.unlock();timerAudio.play(kind);render();}
document.addEventListener('pointerdown',()=>{if(state.timerSound!==false&&(state.pulseDueAt!==null||state.epiDueAt!==null))timerAudio.unlock();});
document.addEventListener('keydown',()=>{if(state.timerSound!==false&&(state.pulseDueAt!==null||state.epiDueAt!==null))timerAudio.unlock();});
function checklistRow(m,item,si,ii){
  const entry=typeof item==='string'?{text:item}:item;
  const id=checklistId(m.id,si,item,ii);
  return `<div class="check-row ${state.checks[id]?'checked':''}">
    <label class="check-control"><input type="checkbox" data-check="${id}" ${state.checks[id]?'checked':''}><span class="custom-check">${icon('check')}</span><span class="check-copy"><span>${esc(entry.text)}</span>${entry.note?`<small>${esc(entry.note)}</small>`:''}</span></label>
    ${entry.protocol||entry.tool?`<div class="check-links">${entry.protocol?source(...entry.protocol):''}${entry.tool?`<button class="button small" data-page="${entry.tool[0]}" ${entry.tool[2]?`data-reference-open="${esc(entry.tool[2])}"`:""}>${esc(entry.tool[1])} ${icon('arrow')}</button>`:''}</div>`:''}
  </div>`;
}
function arrestCodeTools(){return `<div class="arrest-tools">${pulsePanel(state,icon,source)}${epiPanel()}${timerSoundPanel()}<div class="arrest-causes"><h3>Reversible causes</h3><div class="cause-tags">${['Hypoxia','Hypovolemia','Acidosis','Hypo- / hyperkalemia','Hypothermia','Tension pneumothorax','Tamponade','Thrombosis','Toxins','Trauma'].map(c=>`<span>${c}</span>`).join('')}</div></div></div>`;}
function arrestDirections(){return `<aside class="arrest-priority-note" aria-label="Ongoing pads and airway reminder"><strong>Keep reassessing: pads on? Airway in?</strong><p>If either is missing, ensure it happens ASAP.</p><b>Pads first → then airway.</b><strong class="precharge-emphasis">PRE-CHARGE DEFIB before the rhythm / pulse check.</strong><p>Continue CPR while charging; shock only for a shockable rhythm after everyone is clear. Disarm if no shock is indicated.</p></aside>`;}
function sickArrestPanel(m){return `<details class="cardiac-arrest-box sick-arrest-panel" ${state.fields['sick-arrest-open']?'open':''}><summary><span class="sick-arrest-icon">${icon('skull')}</span><span><b>Cardiac arrest</b></span><span class="sick-arrest-expand" aria-hidden="true">+</span></summary><div class="sick-arrest-content">${arrestDirections()}<div class="arrest-rosc-direction"><b>After ROSC, follow C307</b>${source('POST-ROSC CARE · C307',83)}</div>${dispatchTimerPanel(state.fields,icon)}${arrestCodeTools()}<nav class="protocol-links arrest-links" aria-label="Cardiac arrest protocols">${m.arrestRefs.map(ref=>source(...ref)).join('')}<button class="button small" data-page="arrest">Full cardiac arrest checklist ${icon('arrow')}</button></nav></div></details>`;}
function oxygenPriority(m){const item=m.sections[0][1].find(item=>item.id==='main-o2');return item?`<section class="oxygen-priority" aria-label="Oxygen and cabin power first priority">${checklistRow(m,item,0,0)}</section>`:'';}
function checklistSection(m,section,si){
  if(m.id==='cardio'&&si===0)return defibGuide(state.fields,source,icon);
  const code=m.id==='arrest'&&si===1;
  return `<section class="check-section priority-section${m.id==='trauma'?' march-section':''}" data-priority="${checklistColors[m.id]?.[si]||sectionColors[si%sectionColors.length]}" ${m.id==='trauma'?`data-march="${['m','a','r','c','h'][si]}"`:''}>
    <h2><span>${String(si+1).padStart(2,'0')}</span>${section[0]}</h2>
    ${m.id==='sick'&&si===0?`<aside class="callout amber pacing-note" aria-label="Pacing reminder"><b>Pacing: increase current (mA) until capture.</b>Confirm ECG capture and mechanical capture with a matching pulse-ox waveform and pulse.<div>${source('PACING · C302',77)}</div></aside>`:''}
    ${code?arrestDirections():''}
    ${section[1].map((item,ii)=>item.id==='main-o2'?'':checklistRow(m,item,si,ii)).join('')}
    ${code?arrestCodeTools():''}
  </section>`;
}
function detail(m){return `<button class="back" data-page="home">← All checklists</button>
  <div class="page-heading detail-heading"><div><h1>${m.title}</h1></div><div class="large-icon ${m.color}">${icon(m.icon)}</div></div>
  ${oxygenPriority(m)}
  ${m.id==='trauma'?traumaActions(state.fields,source,icon):''}
  ${m.id==='sedation'?sedationDosing(state.fields,source,icon):''}
  ${m.id==='cardio'?'':`<nav class="protocol-links" aria-label="${esc(m.title)} protocols">${m.refs.map(ref=>source(...ref)).join('')}</nav>`}
  <div class="detail-layout"><div>
    ${m.id==='arrest'?dispatchTimerPanel(state.fields,icon):''}

    ${m.id==='sedation'?'<div class="callout purple"><b>Use the indication-specific protocol.</b>Confirm required medical-control orders.</div>':''}
    ${m.id==='ams'?amsFields():''}
    ${m.id==='trauma'?traumaArrestPanel(state.fields,icon,source):''}
    ${['sick','arrest'].includes(m.id)?'':`<div class="checklist-progress"><b>${completed(m)} of ${count(m)} complete</b><span>${Math.round(completed(m)/count(m)*100)}%</span><div class="thin-progress"><span style="width:${completed(m)/count(m)*100}%"></span></div></div>`}
    ${m.sections.map((section,si)=>checklistSection(m,section,si)).join('')}
    ${m.id==='sick'?sickArrestPanel(m):''}
    ${m.id==='arrest'?traumaArrestPanel(state.fields,icon,source):''}
    ${m.id==='ams'?amsCauses():''}
    ${m.id==='trauma'?painPanel(state.fields,source,icon)+burnsPanel(state.fields,source,icon):''}
    ${['trauma','sick'].includes(m.id)?shockPanel(state.fields,source,icon):''}
  </div><aside class="right-rail">${timerPanel()}<section class="panel"><h2>Related tools</h2>${(m.id==='ams'?['sick','trauma']:m.id==='arrest'?['sick','sedation']:m.id==='sick'?['arrest','intubation']:m.id==='intubation'?['sedation','sick']:['intubation','ams']).map(id=>{const r=modules.find(x=>x.id===id);return `<button class="tool-link" data-page="${id}">${icon(r.icon)}${r.short}${icon('arrow')}</button>`}).join('')}<button class="tool-link" data-page="medications">${icon('mystery')}Unusual drugs${icon('arrow')}</button><button class="tool-link" data-page="calculators">${icon('calculator')}Dose & drip calculators${icon('arrow')}</button><button class="tool-link" data-page="pediatric">${icon('child-smile')}Pediatric reference${icon('arrow')}</button></section></aside></div>`;}
function field(id,label,type='text',placeholder=''){return `<label class="field">${label}<input type="${type}" data-field="${id}" value="${esc(state.fields[id])}" placeholder="${placeholder}"></label>`;}
function amsFields(){return `<section class="panel ams-history priority-panel" data-priority="blue"><div class="section-top"><h2>Timeline</h2></div><div class="fields">${field('lkw','Last known well · local date & time','datetime-local')}${field('onset','Symptom onset · local date & time','datetime-local')}<fieldset class="baseline-status"><legend>Altered at baseline?</legend><div class="baseline-options">${[['yes','Yes'],['no','No'],['mild','Maybe a little'],['unknown','Unknown']].map(([value,label])=>`<label class="baseline-option ${state.fields['baseline-altered']===value?'checked':''}"><input type="radio" name="ams-baseline" data-field-choice="baseline-altered" value="${value}" ${state.fields['baseline-altered']===value?'checked':''}><span class="custom-check">${icon('check')}</span><span>${label}</span></label>`).join('')}</div></fieldset>${field('glucose','Blood glucose · mg/dL','number','Value')}</div><label class="inline-check"><input type="checkbox" data-field-check="lkwUnknown" ${state.fields.lkwUnknown?'checked':''}> Last known well is unknown</label><p class="muted">Use this prototype with simulated data. Entries stay in this tab and clear with New encounter.</p></section>`;}
function amsCauses(){return `<section class="panel differential priority-panel" data-priority="purple"><h2>Possible causes</h2><p class="muted">Statuses record your assessment; they are not an automated diagnosis.</p>${causes.map(([id,title,desc],i)=>`<div class="cause-row"><div class="cause-heading"><span class="ams-cause-icon" data-priority="${sectionColors[i%sectionColors.length]}">${icon(amsCauseIcons[id])}</span><div><h3>${title}</h3><p>${desc}</p></div></div><div class="segments" role="group" aria-label="${title}">${[['unassessed','Unassessed'],['in','Ruled in'],['out','Ruled out']].map(([v,l])=>`<button data-cause="${id}" data-value="${v}" aria-pressed="${(state.causes[id]||'unassessed')===v}" class="${(state.causes[id]||'unassessed')===v?'selected '+v:''}">${l}</button>`).join('')}</div></div>`).join('')}</section>`;}
function pediatric(){return pediatricUI(state,source,icon);}
function library(){return `<div class="page-heading"><div><h1>Protocol library</h1></div></div><section class="protocol-hero"><div>${icon('book')}<h2>Southwest Ohio EMS Protocols</h2><p>Academy of Medicine of Cincinnati · 2026</p><span>Version 2.9.26 · Supplied by you</span></div>${source('Open governing protocol')}</section><section class="panel"><h2>Module references</h2>${[{title:'Pediatric cardiac arrest',source:'P601 · P602 · P603 · P600 · Appendix J',refs:[['P601',152],['P602',153],['P603',154],['P600',151]]},{title:'Imminent birth',source:'O800 · O801 · O802 · P600',refs:[['O800',213],['O801',215],['O802',218],['P600',151]]},...modules].map(m=>`<div class="library-row"><div><b>${m.title}</b><p>${m.source}</p></div><div class="library-links">${[...m.refs,...(m.arrestRefs||[])].map(ref=>source(...ref)).join('')}</div></div>`).join('')}<div class="library-row"><div><b>Pediatric medication and energy references</b><p>Appendix J · P601 · P604</p></div>${source('Open Appendix J',237)}</div></section><section class="panel"><h2>Review notes</h2><ul class="review-list"><li>Workflow structure is adapted from your sick patient, cardioversion, intubation, trauma, and AMS checklists. These prompts are not a complete protocol.</li><li>The provided pediatric reference includes 2025 tables. This prototype uses the linked 2026 Appendix J columns.</li><li>Pediatric table entries take precedence where references differ; doses and volumes are displayed as printed. Missing entries show N/A.</li><li>Age presets are estimates. The pediatric age table remains an estimate; the medication reference calculates from entered patient weight under specific protocols.</li><li>Unusual drugs and stock volumes are indication-specific. Confirm concentrations and department clinical approval before field use.</li></ul></section><section class="panel"><h2>About this prototype</h2><p>Checklists, AMS assessment, timer, and pediatric selection share one encounter in this browser tab. No patient account, backend patient record, or offline guarantee is provided. Use simulated data while reviewing. New encounter clears tab-stored entries.</p></section>`;}
function dialog(){return `<div class="modal-backdrop"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="module-icon red">${icon('reset')}</div><h2 id="dialog-title">Start a new encounter?</h2><p>This clears all checklist progress, AMS entries, pediatric selections, calculator inputs, magnesium concentration confirmation, post-call reminders, trauma timestamps, shock / burn inputs, the dispatch timer, pulse-check timer, epi timer, event timer, and stopwatch in this tab. Your supplies needed list is kept for restocking.</p><div><button class="button" data-action="cancel">Keep current encounter</button><button class="button primary" data-action="confirm-new">Clear & start new</button></div></section></div>`;}
function rememberReferenceOpen(){document.querySelectorAll('[data-ref-open]').forEach(el=>{if(el.open)referenceUI.open.add(el.dataset.refOpen);else referenceUI.open.delete(el.dataset.refOpen);});}
function render(){rememberReferenceOpen();rememberTraumaArrest(state.fields);const arrestPanel=document.querySelector('.sick-arrest-panel');if(arrestPanel)state.fields['sick-arrest-open']=arrestPanel.open;document.querySelector('#app').innerHTML=shell();document.title=`${pageLabel()} · Woodlawn FD`;if(state.fields.lkwUnknown){const lkw=document.querySelector('[data-field="lkw"]');if(lkw)lkw.disabled=true;}if(modal)document.querySelector('[data-action="cancel"]').focus();}
function refreshReference(el){
  const id=el.id,y=window.scrollY,selection=el.type==='text'?el.selectionStart:null;
  render();window.scrollTo(0,y);const next=document.getElementById(id);if(next){next.focus({preventScroll:true});if(selection!==null&&next.type==='text')next.setSelectionRange(selection,selection);}
}
function go(id){page=id;location.hash=id;render();window.scrollTo(0,0);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page){if(b.dataset.cardioSedation){state.fields['sedation-midazolam-open']=true;state.fields['sedation-group']='cardioversion';save();}if(b.dataset.referenceOpen){referenceUI.search='';referenceUI.protocol='';referenceUI.category='';referenceUI.open.add('drug-'+b.dataset.referenceOpen);}go(b.dataset.page);if(b.dataset.cardioSedation){document.querySelector(`[data-sedation-path="${b.dataset.cardioSedation}"]`)?.scrollIntoView({block:'start'});}if(b.dataset.referenceOpen){const card=document.querySelector(`[data-ref-open="drug-${b.dataset.referenceOpen}"]`);card?.scrollIntoView({block:'start'});card?.querySelector('summary')?.focus({preventScroll:true});}}if(b.dataset.useWeight){const kg=kgFrom(state.fields['convert-value'],state.fields['convert-unit']??'lb');if(kg!==null){state.fields['ref-weight']=String(kg);state.fields['ref-weight-unit']='kg';save();render();}}if(b.dataset.age!==undefined){state.age=Number(b.dataset.age);save();render();}if(b.dataset.cause){state.causes[b.dataset.cause]=b.dataset.value;save();render();}switch(b.dataset.action){case 'new':modal=true;render();break;case 'cancel':modal=false;render();break;case 'confirm-new':setConcentration('magnesium','');timerAudio.stop();document.querySelector('.sick-arrest-panel')?.remove();document.querySelector('.trauma-arrest-panel')?.remove();state=blank();referenceUI.search='';referenceUI.protocol='';referenceUI.category='';referenceUI.open.clear();save();modal=false;go('home');break;case 'timer':if(state.running){state.elapsed+=Date.now()-state.started;state.running=false;state.started=null;}else{state.started=Date.now();state.running=true;}save();render();break;case 'pulse-cycle':timerAudio.unlock();state.pulseDueAt=Date.now()+120_000;clearTimerAlerts(state,'pulse');save();render();break;case 'clear-pulse':state.pulseDueAt=null;clearTimerAlerts(state,'pulse');save();render();break;case 'toggle-timer-sound':state.timerSound=state.timerSound===false;if(state.timerSound)timerAudio.unlock();else timerAudio.stop();save();render();break;case 'test-pulse-sound':testTimerSound('pulse');break;case 'test-epi-sound':testTimerSound('epi');break;case 'epi-dose':timerAudio.unlock();clearTimerAlerts(state,'epi');state.epiDueAt=Date.now()+epiInterval()*60_000;save();render();break;case 'clear-epi':state.epiDueAt=null;clearTimerAlerts(state,'epi');save();render();break;case 'reset-timer':state.elapsed=0;state.running=false;state.started=null;save();render();break;}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.fieldChoice){state.fields[el.dataset.fieldChoice]=el.value;save();const y=window.scrollY;render();window.scrollTo(0,y);document.querySelector(`[data-field-choice="${el.dataset.fieldChoice}"][value="${el.value}"]`)?.focus({preventScroll:true});}if(el.dataset.refField&&el.tagName==='SELECT'){state.fields[el.dataset.refField]=el.value;save();refreshReference(el);}if(el.dataset.stock){setConcentration(el.dataset.stock,el.value);refreshReference(el);}if(el.id==='reference-protocol'||el.id==='reference-category'){referenceUI[el.id==='reference-protocol'?'protocol':'category']=el.value;refreshReference(el);}if(el.dataset.check){state.checks[el.dataset.check]=el.checked;save();const y=window.scrollY;render();window.scrollTo(0,y);document.querySelector(`[data-check="${el.dataset.check}"]`)?.focus({preventScroll:true});}if(el.dataset.fieldCheck){state.fields[el.dataset.fieldCheck]=el.checked;if(el.dataset.fieldCheck==='lkwUnknown'&&el.checked)state.fields.lkw='';save();const y=window.scrollY;render();window.scrollTo(0,y);document.querySelector(`[data-field-check="${el.dataset.fieldCheck}"]`)?.focus({preventScroll:true});}if(el.id==='epi-interval'&&state.epiDueAt===null){state.epiInterval=Number(el.value);save();render();}});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.refField&&el.tagName==='INPUT'){state.fields[el.dataset.refField]=el.value;save();refreshReference(el);}if(el.dataset.stockCustom){setConcentration(el.dataset.stockCustom,el.value,true);refreshReference(el);}if(el.id==='reference-search'){referenceUI.search=el.value;refreshReference(el);}if(el.dataset.field){state.fields[el.dataset.field]=el.value;save();}if(el.id==='search'||el.id==='med-search'){const pos=el.selectionStart;if(el.id==='search')query=el.value;else{state.filter=el.value;save();}render();const replacement=document.getElementById(el.id);replacement.focus();replacement.setSelectionRange(pos,pos);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal){modal=false;render();}if(e.key==='Tab'&&modal){const focusable=[...document.querySelectorAll('.dialog button')];if(e.shiftKey&&document.activeElement===focusable[0]){e.preventDefault();focusable.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===focusable.at(-1)){e.preventDefault();focusable[0].focus();}}if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){const s=document.getElementById('supply-search')||document.getElementById('search')||document.getElementById('med-search');if(s){e.preventDefault();s.focus();}}});
document.addEventListener('toggle',e=>{if(e.target.matches('.sick-arrest-panel')){state.fields['sick-arrest-open']=e.target.open;save();}},true);
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'home';render();});
setInterval(()=>{
  document.querySelectorAll('.timer-digits').forEach(e=>e.textContent=timerText());
  refreshDispatchTimer(state.fields);
  refreshPulseTimer(state);
  processTimerAlerts(state,timerAudio,save);
  refreshTimerSoundStatus();
  const epi=document.querySelector('.epi-panel');
  if(epi){epi.querySelector('.epi-digits').textContent=epiText();const status=epi.querySelector('.epi-status');if(status.textContent!==epiStatus())status.textContent=epiStatus();for(const phase of ['warning','due'])epi.classList.toggle(phase,timerPhase(state.epiDueAt,epiInterval()*60,EPI_WARNING)===phase);}
},250);
bindStopwatch(()=>state,save);
bindArrestBirth(()=>state,save);
bindArrestTools(()=>state,save,render);
bindDefibGuide(()=>state,save,render);
bindSedationDosing(()=>state,save,render);
bindTraumaArrest(()=>state,save);
bindPostCall(render);
bindClinicalTools(()=>state,save,render);
render();
